for task, class_name, fields in [
    (TASKS[0], 'Ticket', [('name', 'String'), ('price', 'int')]),
    (TASKS[1], 'Sensor', [('name', 'String'), ('reading', 'int')]),
    (TASKS[2], 'CafeOrder', [('dish', 'String'), ('price', 'int')]),
    (TASKS[3], 'Book', [('title', 'String'), ('pages', 'int')]),
]:
    checks = f'Class<?> c = cls("{class_name}"); need(c != null, "Создай класс {class_name}");\ntry {{\n'
    for name, typ in fields:
        checks += f'Field f_{name} = c.getDeclaredField("{name}"); need(f_{name}.getType() == {typ}.class && !Modifier.isStatic(f_{name}.getModifiers()), "Поле {name} должно иметь тип {typ} и быть без static");\n'
    checks += f'}} catch (ReflectiveOperationException e) {{ need(false, "Добавь поля класса {class_name} по условию"); }}'
    task.checks = checks
